import {
  compareRationalTimes,
  readOtioDocument,
  resolveOtioAnchor,
  sourceSpansForOtioRange,
} from './packages/relic-format/src/index.ts';

const time = (value: number, rate = 24) => ({ value, rate });
const range = (start: number, duration: number, rate = 24) => ({
  start_time: time(start, rate),
  duration: time(duration, rate),
});
const authoredRange = (start: number, duration: number, rate = 24) => ({
  OTIO_SCHEMA: 'TimeRange.1',
  start_time: { OTIO_SCHEMA: 'RationalTime.1', ...time(start, rate) },
  duration: { OTIO_SCHEMA: 'RationalTime.1', ...time(duration, rate) },
});
const clip = (id: string, start: number) => ({
  OTIO_SCHEMA: 'Clip.1',
  name: id,
  metadata: { relic: { id } },
  source_range: authoredRange(start, 1),
  media_reference: {
    OTIO_SCHEMA: 'ExternalReference.1',
    target_url: `media/${id}.mov`,
    available_range: authoredRange(0, 1000),
  },
});
const makeDocument = (children: unknown[], duration?: number) =>
  readOtioDocument(JSON.stringify({
    OTIO_SCHEMA: 'Timeline.1', name: 'Boundary', metadata: { relic: { id: 'T' } },
    ...(duration === undefined ? {} : { source_range: authoredRange(0, duration) }),
    tracks: {
      OTIO_SCHEMA: 'Stack.1', metadata: { relic: { id: 'S' } },
      children: [{ OTIO_SCHEMA: 'Track.1', kind: 'Video', name: 'V',
        metadata: { relic: { id: 'V' } }, children }],
    },
  }));
const cut = makeDocument([clip('A', 100), clip('B', 200)]);
const gap = { OTIO_SCHEMA: 'Gap.1', metadata: { relic: { id: 'G' } },
  source_range: authoredRange(0, 1) };
const extended = makeDocument([clip('A', 100), gap, clip('B', 200)], 4);
const results = [];
for (const [label, document, selected, track, item] of [
  ['before-cut', cut, range(1999, 0, 48000), 'V'],
  ['at-cut', cut, range(2000, 0, 48000), 'V'],
  ['clip-as-track', cut, range(0, 0), 'A'],
  ['clip-as-track-with-item', cut, range(0, 0), 'A', 'A'],
  ['track-endpoint', cut, range(2, 0), 'V'],
  ['timeline-endpoint', cut, range(2, 0), null],
  ['outside-track', cut, range(3, 0), 'V'],
  ['outside-timeline', cut, range(3, 0), null],
  ['full-track-range', cut, range(0, 2), 'V'],
  ['explicit-gap', extended, range(1.5, 0), 'V'],
  ['empty-timeline-tail', extended, range(3.5, 0), null],
  ['past-shorter-track', extended, range(3.5, 0), 'V'],
] as const) {
  const result = resolveOtioAnchor({
    kind: 'otio', v: 1, relic_version: 1,
    document_sha256: document.document_sha256,
    timeline_id: 'T', track_id: track,
    ...(item === undefined ? {} : { item_id: item }), range: selected,
    snapshot: { timeline: 'Boundary', track, item: item ?? null },
  }, document);
  results.push({ label, status: result.status,
    spans: result.source_spans.map(span => ({ node: span.node_id, source: span.source_range })),
    mapped_range: result.mapped_range, diagnostics: result.diagnostics });
}
console.log(JSON.stringify({
  comparison: compareRationalTimes(time(1999, 48000), time(1, 24)),
  directSpans: sourceSpansForOtioRange(cut, 'T', 'V', range(1999, 0, 48000))
    .map(span => ({ node: span.node_id, source: span.source_range })),
  results,
}, null, 2));
